import{_ as n,l,o as e,c as i,v as r,p as E,x as o,d as s,i as h,S as d}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"展期收益","description":"","frontmatter":{"title":"展期收益","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/roll-yield.md","filePath":"quant/roll-yield.md","lastUpdated":1789023840000}'),m={name:"quant/roll-yield.md"};function p(u,a,B,c,A,_){const t=l("Mermaid");return e(),i("div",null,[a[1]||(a[1]=r('<h1 id="展期收益" tabindex="-1">展期收益 <a class="header-anchor" href="#展期收益" aria-label="Permalink to &quot;展期收益&quot;">​</a></h1><div class="epigraph"><p>商品期货的长期超额并不是现货指数的简单翻版；合约必须展期，期限结构上的滚仓损益可以在样本里盖过现货腿，但它不是一笔可进账的票息。</p><footer>—— Erb &amp; Harvey, The Strategic and Tactical Value of Commodity Futures, Financial Analysts Journal, 2006</footer></div><p>持有近月期货到期前要换成更远的合约，买卖价差落在两条不同到期的价格上。若曲线向下倾斜（近贵远贱），多头卖掉贵的、买进贱的，账面出现正的展期收益（roll yield / roll return）；若曲线正向，多头做相反的事，展期为负。Erb 与 Harvey 把商品组合的超额拆成现货贡献与展期贡献，并指出许多投资者以为自己在「投资原油现货」，实际在投资一条被指数规则定义的期货曲线。Gorton 与 Rouwenhorst 的长期事实、Gorton–Hayashi–Rouwenhorst 的库存基本面，都要求把这一项单独记账。Working 的仓储理论解释它何时为正：库存紧、便利收益高、曲线贴水。它何时能被你赚走，则取决于滚仓日历、冲击与是否有人提前在同一窗口交易。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>一个简化的分解把持有近月再展期到次近月的超额写成</p> \\[R_{\\mathrm{fut}} \\approx R_{\\mathrm{spot}} + R_{\\mathrm{roll}} + \\varepsilon_{\\mathrm{collateral}}, \\]<p>其中 \\(R_{\\mathrm{roll}}\\) 常被近似为 \\((F_{\\mathrm{near}}-F_{\\mathrm{next}})/F_{\\mathrm{next}}\\) 一类的期限结构斜率（符号约定随多空与报价方式而变），抵押收益是保证金账户上的利息。问题有三层。第一，展期收益不是现金券息：没有人在滚仓日把基差差额打到你账上；你卖一张合约、买另一张，盯市盈亏已经把两条腿的价格差写进保证金。第二，斜率是事前状态，\\(R_{\\mathrm{spot}}\\) 是事后现货变动，两者相关——Working 的逻辑里，贴水往往伴随现货预期回落或已经很高的现货，把历史平均正展期当成无条件期望会重复计算。第三，指数与自营的滚仓规则不同，同一条曲线上的 \\(R_{\\mathrm{roll}}\\) 不是同一个数。</p><p>Erb 与 Harvey（2016）专门清理误读：把 roll yield 理解成「持有商品的租赁收入」会高估可花费收益，也会在 contango 加深时低估亏损。Main、Irwin、Sanders 与 Smith 一类工作进一步争辩：展期收益在多大程度上只是未来现货收益的预报，而不是独立的第三种 alpha。对交易者，预报与票息的会计差别是：前者在现货腿实现时对冲掉，后者在你错误地按票息加杠杆时变成爆仓。</p><h3 id="指数滚仓不是仓储套利" tabindex="-1">指数滚仓不是仓储套利 <a class="header-anchor" href="#指数滚仓不是仓储套利" aria-label="Permalink to &quot;指数滚仓不是仓储套利&quot;">​</a></h3><p>GSCI 一类指数历史上在确定的交易日把近月换成远月，流动性好、规则公开。这不是 Working 意义上的「把货从 \\(T_1\\) 存到 \\(T_2\\)」：指数不持有仓单，只持有期货。正展期来自卖高买低的期货价差，对冲的是曲线，不是仓储实物的持有成本回收。因此 <a href="/quant/cash-and-carry">期现套利</a> 的利润边界不能用来给指数多头的展期收益做估值。指数在贴水市场里「看起来像收租」，在升水市场里「看起来像付租」，都是曲线几何加上被动规则，不是你租出了原油。</p><p><span class="marginnote">用收盘价在滚仓日当天计算展期，会把当日现货冲击算进 \\(R_{\\mathrm{roll}}\\)。应把展期腿定义成两张期货的价差成交，把现货或近月的方向性变动留在 \\(R_{\\mathrm{spot}}\\)。否则战术信号会在油价跳的日子里同时「展期很强」和「现货很强」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>先固定合约序列与滚仓窗口，再用可成交的中间价或保守的主动侧报价计算价差。年化时除以真实的持有天数，而不是一律除以 365 再假装连续曲线。截面策略若「做多最贴水、做空最升水」，必须同步控制库存分位与波动：Gorton–Hayashi–Rouwenhorst 表明基差与库存相关，单纯排序会在低库存品种上堆叠流动性差、挤仓风险高的合约。容量上，近月深度在滚仓周被指数与复制产品共用，冲击是状态依赖的，见 Bessembinder、Carrion、Tuttle 与 Venkataraman 对可预测交易周围流动性的讨论，以及 <a href="/quant/roll-volume-oi">展期成交量与持仓</a>。</p><p>与 <a href="/quant/contango-backwardation">Contango 与 Backwardation</a> 对齐：展期收益的符号由曲线斜率决定，期望超额还取决于现货漂移与风险溢价。回测应报告三列：现货腿、展期腿、抵押利息；并报告滚仓窗口内的实现滑点。把三列加总再挑参数，会把拥挤窗口的负滑点藏进「模型误差」。</p><h3 id="成本、杠杆与假票息" tabindex="-1">成本、杠杆与假票息 <a class="header-anchor" href="#成本、杠杆与假票息" aria-label="Permalink to &quot;成本、杠杆与假票息&quot;">​</a></h3><p>展期看起来像票息，最容易被加杠杆。保证金只覆盖期货，名义杠杆可以把年化几个点的负 contango 放大成本金级亏损，2008 年后若干商品 ETN 的路径是这一机制的公开案例。成本项包括：两次买卖价差（出近月、进远月）、窗口内冲击、以及日历价差本身的买卖价差。远月通常更宽；指数为了深度选择次近月，自营若去更远的合约「躲滚仓」，展期公式里的斜率会变，流动性折扣会升。借货与仓储只出现在你真的做期现或跨期实物交割时；纯期货展期没有仓储票息，只有曲线。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>仓储机制：库存低 → 便利收益高 → 近月相对远月贵 → 多头展期为正。这是 Working 与 Fama–French 的通道。风险溢价机制：即便曲线升水，期货仍可低于期望现货，多头赚的是溢价而不是展期；展期为负、溢价为正时，两项对冲，净结果依赖样本。Erb–Harvey 的战术含义是曲线状态可以当配置信号，但信号的经济来源是仓储与套期保值压力的混合物，衰减取决于库存补充速度，不是 OU 半衰期估计。</p><p>金融化机制：被动指数把展期从分散的商业滚仓，变成可预测的日历需求。Mou 讨论在公开滚仓窗口前抢跑；抢跑把部分本该属于指数的展期转移到日历价差交易者。于是历史平均正展期里有一块是「那时指数还小、曲线还更常贴水」，不是策略的稳态 alpha。Cheng–Xiong 综述之后，再把 1990–2004 的平均展期当成 2010 年代的期望，是机制已经变了还在用旧均值。</p><h3 id="破裂-曲线翻转、停仓与现金结算" tabindex="-1">破裂：曲线翻转、停仓与现金结算 <a class="header-anchor" href="#破裂-曲线翻转、停仓与现金结算" aria-label="Permalink to &quot;破裂：曲线翻转、停仓与现金结算&quot;">​</a></h3><p>农产品在收获窗口曲线可以从贴水翻成升水，展期符号几天内对调，仓位若按月频排序来不及。能源在交割路径断裂（管道、飓风、战略储备释放）时近月可以与次近月脱钩，展期收益变成挤仓损益。现金结算指数与商品期货的展期还不是同一对象：结算价若来自现货窗口，期货曲线的滚仓亏损不会在指数点位里以同一方式出现。金属 LME 的日期结构、上期所与 CME 的交割月规则不同，把一个市场的 roll yield 公式套到另一个市场，符号都会错。</p><p><span class="marginnote">正展期经常出现在现货已经大涨、库存已经很低的时候。这时继续加多头杠杆，风险是现货回补与曲线转正同时发生——两项一起为负。Gorton–Hayashi–Rouwenhorst 要把库存拉进条件期望，正是为了阻止把无条件平均展期当成永远可领的租金。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>不要把 ETF/ETN 的年化「roll yield」宣传数字当成可交易期望：那是对历史曲线的会计，扣费、跟踪误差与提前赎回条款另计。不要在滚仓周用收盘斜率加大战术权重，你与指数同侧。不要用远月不流动合约把 contango「做空到消失」——消失的是你的报价，不是仓储。与 <a href="/quant/calendar-spread-arb">跨期套利</a> 的边界：主动做日历价差是在交易斜率的变化；被动展期是在缴纳或收取当前斜率。两者的成本函数不同，不能共用一张容量表。</p><p>报告里写清：合约、滚仓日、成交假设、库存条件、以及现货腿与展期腿的协方差。Erb–Harvey（2006）给出的是战略与战术分解，不是一张品种打分表；Gorton–Rouwenhorst 给出的是长期组合事实。单品种原油或天然气的展期，方差由现货主导，展期只是慢变量，用它当主信号必须接受库存报告日的跳跃，见<a href="/quant/inventory-curve">库存报告与曲线</a>。</p><p><span class="marginnote">抵押利息属于资金台，不属于商品风险溢价。把 T-bill 收益加进「商品总回报」再和股票比夏普，是 Erb–Harvey 与 Gorton–Rouwenhorst 都讨论过的口径问题：超额应用期货收益，不要把无风险利率算进 alpha。</span></p>',26)),(e(),E(d,null,{default:o(()=>[h(t,{id:"mermaid-74",class:"mermaid",graph:"flowchart%20TD%0A%20%20CURVE%5B%22%E8%BF%91%E6%9C%88%E7%9B%B8%E5%AF%B9%E8%BF%9C%E6%9C%88%E7%9A%84%E6%96%9C%E7%8E%87%22%5D%20--%3E%20ROLL%5B%22%E5%B1%95%E6%9C%9F%E6%94%B6%E7%9B%8A%E7%AC%A6%E5%8F%B7%22%5D%0A%20%20INV%5B%22%E5%BA%93%E5%AD%98%20%2F%20%E4%BE%BF%E5%88%A9%E6%94%B6%E7%9B%8A%22%5D%20--%3E%20CURVE%0A%20%20IDX%5B%22%E6%8C%87%E6%95%B0%E6%BB%9A%E4%BB%93%E8%A7%84%E5%88%99%22%5D%20--%3E%20EXEC%5B%22%E5%8D%96%E8%BF%91%E4%B9%B0%E8%BF%9C%E7%9A%84%E6%88%90%E4%BA%A4%22%5D%0A%20%20ROLL%20--%3E%20EXEC%0A%20%20EXEC%20--%3E%20SLIP%5B%22%E7%AA%97%E5%8F%A3%E5%86%B2%E5%87%BB%E4%B8%8E%E6%8A%A2%E8%B7%91%22%5D%0A%20%20SPOT%5B%22%E7%8E%B0%E8%B4%A7%E5%8F%98%E5%8A%A8%22%5D%20--%3E%20PNL%5B%22%E6%9C%9F%E8%B4%A7%E8%B6%85%E9%A2%9D%22%5D%0A%20%20EXEC%20--%3E%20PNL%0A%20%20COL%5B%22%E4%BF%9D%E8%AF%81%E9%87%91%E6%8A%B5%E6%8A%BC%E5%88%A9%E6%81%AF%22%5D%20--%3E%20PNL%0A%20%20PNL%20--%3E%20SPLIT%5B%22%E5%88%86%E5%BC%80%E8%AE%B0%E8%B4%A6%3A%20%E7%8E%B0%E8%B4%A7%20%2F%20%E5%B1%95%E6%9C%9F%20%2F%20%E6%8A%B5%E6%8A%BC%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>展期收益来自把近月换成远月时的期限结构，符号随 contango / backwardation 而变；它是盯市损益，不是仓单租金。</li><li>Erb–Harvey（2006, 2016）要求把现货腿与展期腿分开，并纠正「roll yield 是票息」的误读。</li><li>Working 的仓储与 Gorton–Hayashi–Rouwenhorst 的库存基本面解释展期何时为正；无条件历史均值不能当稳态租金。</li><li>指数公开滚仓创造可预测需求，滑点与抢跑会转移展期；容量在滚仓周下降。</li><li>杠杆会把缓慢的负升水变成本金级路径风险；成本按两次成交与远月价差计。</li><li>出处：Erb and Harvey, <em>FAJ</em>, 2006 与 2016；Gorton and Rouwenhorst, <em>FAJ</em>, 2006；Gorton, Hayashi and Rouwenhorst, <em>Review of Finance</em>, 2013；Working, <em>AER</em>, 1949；Fama and French, <em>Journal of Business</em>, 1987；Mou, Columbia working paper on the Goldman Roll；Bessembinder, Carrion, Tuttle and Venkataraman, <em>JFE</em>, 2016；Hull, <em>Options, Futures, and Other Derivatives</em>。</li></ul>',2))])}const F=n(m,[["render",p]]);export{C as __pageData,F as default};
